import { Button, ModalBody, ModalContent, ModalFooter, ModalHeader, Modal } from "@heroui/react"
import React, { useEffect, useState } from 'react'
import IconButton from '@mui/material/IconButton';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import RemoveIcon from '@mui/icons-material/Remove';
export default function OrderSummaryModal({ openSummaryModal, setopenSummaryModal, handlePay,handleDeleteOrderItem,handleDeductQuantity, handleAddQuantity }) {

    const [selectedItems, setselectedItems] = useState(localStorage.getItem("selectedItems") ? JSON.parse(localStorage.getItem("selectedItems")) : [])
    const [totalAmount, settotalAmount] = useState(0.00)

    useEffect(() => {

        settotalAmount(selectedItems.reduce((acc, item) => acc + parseFloat(item.price * item.quantity), 0))

    }, [selectedItems])





    return (
        <Modal
        className='mt-10'
            isOpen={openSummaryModal}



            placement="center"
            fullScreen
            

        >
            <ModalContent>


                {(onClose) => (
                    <>


                        <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">Order Summary</ModalHeader>
                        <ModalBody>

                            {selectedItems && selectedItems.length ? <div className='flex justify-between items-center font-bold '><span>Items: {selectedItems.length}</span> <span>Amount: KES {totalAmount.toFixed(2)}</span></div> : <p className='text-center font-bold text-medium'>No items</p>}
                            {selectedItems && selectedItems.length ? <div className='overflow-y-scroll'>{selectedItems.map((item, index) => <div className='border-small shadow-md p-2'>

                                <p className='text-medium font-medium'> {item.quantity} x {item.title} @ KES {item.price}</p>
                                <p className='font-bold'><span>Sub Total: </span><span> KES {parseFloat(item.quantity * item.price).toFixed(2)}</span></p>
                                <div className='flex justify-between items-center'>


                                    <IconButton  onClick= {()=>handleDeductQuantity(item)}color="primary">
                                        <RemoveIcon />
                                    </IconButton>
                                    <p>{item && item.quantity ? item.quantity.toString() : 0}</p>


                                    <IconButton onClick= {()=>handleAddQuantity(item)} color="primary">
                                        <AddIcon />
                                    </IconButton>

                                    <IconButton onClick={() => handleDeleteOrderItem(item)} aria-label="delete" color="error">
                                        <DeleteIcon />
                                    </IconButton>
                                </div>

                            </div>)}</div> : <p></p>}

                        </ModalBody>
                        <ModalFooter className=' justify-between'>
                            <Button color="danger" variant="flat" onPress={() => setopenSummaryModal(false)}>
                                Cancel
                            </Button>

                            <Button color="primary" variant="flat" onPress={() => handlePay()}>
                                Pay
                            </Button>


                        </ModalFooter>



                    </>
                )}
            </ModalContent>
        </Modal>)
}
